def recite(start, take=1):
    verses = []
    for n in range(start, start - take, -1):
        if verses:
            verses.append("")
        verses.extend(_verse(n))
    return verses


def _bottles(n):
    if n == 0:
        return "No more bottles of beer", "no more bottles of beer"
    if n == 1:
        return "1 bottle of beer", "1 bottle of beer"
    return f"{n} bottles of beer", f"{n} bottles of beer"


def _verse(n):
    first = _bottles(n)
    if n == 0:
        return [
            f"{first[0]} on the wall, {first[1]}.",
            "Go to the store and buy some more, 99 bottles of beer on the wall.",
        ]
    second = _bottles(n - 1)
    action = "Take it down" if n == 1 else "Take one down"
    return [
        f"{first[0]} on the wall, {first[1]}.",
        f"{action} and pass it around, {second[1]} on the wall.",
    ]
